<template><div><div class="page-title"><div><p class="eyebrow">MENU</p><h1>菜单管理</h1><p>管理上架菜品、价格和展示顺序。</p></div><el-button type="primary" @click="$router.push('/admin/products/new')">＋ 新增菜品</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-table :data="products" stripe><el-table-column label="照片" width="90"><template #default="s"><img class="table-photo" :src="resolveImageUrl(s.row.image)||fallback"/></template></el-table-column><el-table-column prop="name" label="菜名" min-width="130"/><el-table-column prop="category" label="分类" width="90"/><el-table-column label="价格" width="100"><template #default="s">¥{{s.row.price}}</template></el-table-column><el-table-column label="状态" width="90"><template #default="s"><el-tag :type="s.row.status==='active'?'success':'info'">{{s.row.status==='active'?'上架':'下架'}}</el-tag></template></el-table-column><el-table-column prop="sortOrder" label="排序" width="80"/><el-table-column label="操作" width="180"><template #default="s"><el-button link type="primary" @click="$router.push(`/admin/products/edit/${s.row.id}`)">编辑</el-button><el-button link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table></div></template>
<script setup lang="ts">import {ref,onMounted,watch} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import {api,resolveImageUrl,type Product} from '../api';import {activeStoreId} from '../storeContext';const products=ref<Product[]>([]),error=ref(''),fallback='https://placehold.co/100x80/f3eee4/53645a?text=Dish';async function load(){try{products.value=(await api.get('/products',{params:{storeId:activeStoreId.value,includeInactive:'1'}})).data.data}catch(e:any){error.value=e.message}}async function remove(p:Product){try{await ElMessageBox.confirm('确定要删除这个菜品吗？','确认删除',{type:'warning'});await api.delete(`/products/${p.id}`);ElMessage.success('已删除');load()}catch(e:any){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message||'删除失败')}}onMounted(load);watch(activeStoreId,load);</script>
